A TOML parser written in zig that targets v1.0 specs of TOML.

## Supported zig versions
✅ [0.14.0](https://ziglang.org/documentation/0.14.0/)

## Test suite coverage
[toml-test](https://github.com/toml-lang/toml-test) is a language-agnostic test suite to verify the correctness of TOML parsers and writers.

The parser fails 2 tests in the invalid set that involves dotted keys, the 2 tests expect the parser to reject a niche confusing use case of toml dotted keys however they are accepted by the parser. this might get fixed in the future but for now it's not a priority.

## Usage
```zig
const std = @import("std");
const toml = @import("tomlz");
const io = std.io;
var gpa: std.heap.DebugAllocator(.{}) = .init;

pub fn main() !void {
    defer std.debug.assert(gpa.deinit() == .ok);
    const allocator = gpa.allocator();

    // the toml parser takes an allocator and uses it internally
    for all allocations.
    var p = toml.Parser.init(allocator);
    // when done deinit the parser to free all allocated resources.
    defer p.deinit();


    const toml_input =
        \\message = "Hello, World!"
    ;
    // the TOML parser accepts a io.StreamSource as an input source.
    // the StreamSource should live as long as the parser.
    var toml_stream = io.StreamSource{
        .const_buffer = io.FixedBufferStream([]const u8){
            .buffer = src,
            .pos = 0,
        },
    };

    // use parse to start parsing the input source.
    var parsed = p.parse(&toml_stream) catch {
        std.log.err("The stream isn't a valid TOML document, {}\n",.{err});
        // handle error.
    };

    // parsed is of type toml.TomlTable which is an alias to
    // std.StringHashMap(TomlValue).
    // toml.TomlValue type is a union with the following fields:
    // pub const TomlValue = union(TomlType) {
    //     Boolean: bool,
    //     Integer: i64,
    //     Float: f64,
    //     String: []const u8,
    //     Array: []TomlValue,
    //     Table: TomlTable,
    //     TablesArray: []TomlTable,
    //     DateTime: DateTime,
    // };
    // aside from DateTime all other types are standard zig types.
    // all data returned by the parser is owned by the parser and
    // will be freed once deinit is called or if parse() is called again,
    // consider cloning anything you need to outlive the parser.


    var iter = parsed.iterator();
    while (iter.next()) |pair| {
        // the key is of type []const u8.
        std.debug.print("\n{s} => ", .{pair.key_ptr.*});
        switch (pair.value_ptr.*) {
            // ... do whatever
        }
    }
}
```

## Build options
The build.zig file contains various options that can be used to customize
the behaviour of the parser when building, check it out for more details.

# faker.zig
A faker library for Zig

# Examples
```Zig
const faker = @import("faker");
const std = @import("std");
const en = faker.locale.en;
const base = faker.locale.base;
const print = std.debug.print;

fn GenericsType(comptime T: type) type {
    return struct {
        data: T,
    };
}

pub fn main() !void {
    // create faker with locales and random
    const allocator = std.heap.page_allocator;
    var rng = std.rand.DefaultPrng.init(0);
    const f = Faker(.{ .locales = .{ en, base } }).init(allocator, rng.random());

    // primitive types
    const u8_val = f.dummy(u8);
    print("u8_val = {}\n", u8_val);

    const f32_val = f.dummy(f32);
    print("f32_val = {}\n", f32_val);

    // arrays and vectors
    const arr_val = f.dummy([3]u8);
    print("arr_val = {}\n", arr_val);

    const multi_dim_arr_val = f.dummy([2][3]u8);
    print("multi_dim_arr_val = {}\n", multi_dim_arr_val);

    const vec_val = f.dummy(@Vector(4, i32));
    print("vec_val = {}\n", vec_val);

    // struct
    const Point = struct {
        x: f32,
        y: f32,
    };
    const point_val = f.dummy(Point);
    print("point_val = {}\n", point_val);

    const generic_val = f.dummy(GenericsType(u8));
    print("generic_val = {}\n", generic_val);

    // enum
    const EnumType = enum {
        ok,
        not_ok,
    };
    const enum_val = f.dummy(EnumType);
    print("enum_val = {}\n", enum_val);

    // union
    const UnionType = union(EnumType) {
        ok: u8,
        not_ok: void,
    };
    const union_val = f.dummy(UnionType);
    print("union_val = {}\n", union_val);

    // strings
    const str_val = f.dummy([]const u8);
    print("str_val = {s}\n", str_val);

    // customization
    const BlogUnmanaged = struct {
        const Self = @This();

        id: u32,
        tag: []const u8,
        title: []u8,
        body: []u8,

        pub fn deinit(self: Self, allocator: Allocator) void {
            allocator.free(self.title);
            allocator.free(self.body);
        }

        pub const @"faker.fields" = struct {
            pub const tag = .{ "color", "human" };
            pub const title = .{ "lorem", "words", .{ .min = 5, .max = 10 } };

            pub fn body(comptime opt: anytype, f: faker.Faker(opt)) []u8 {
                return f.lorem.words(.{ .min = 20, .max = 30 });
            }
        };
    };

    const blog = f.dummy(BlogUnmanaged);
    defer blog.deinit(f.allocator);
    std.debug.print("blog.id {d}\n", .{blog.id});
    std.debug.print("blog.tag {s}\n", .{blog.tag});
    std.debug.print("blog.title {s}\n", .{blog.title});
    std.debug.print("blog.body {s}\n", .{blog.body});

    // user impls
    const non_null_option = struct {
        pub fn is(
            comptime T: type,
        ) bool {
            return @typeInfo(T) == .Optional;
        }

        pub fn dummy(comptime T: type, comptime opt: anytype, f: faker.Faker(opt)) T {
            const info = @typeInfo(T).Optional;
            return f.dummy(info.child);
        }
    };

    const User = struct {
        const Self = @This();
        id: u32,
        friends: ?std.ArrayList(u8),

        pub fn deinit(self: Self) void {
            if (self.friends) |v| v.deinit();
        }
    };
    const f2 = faker.Faker(.{
        .locales = .{ en, base },
        .user_impls = .{non_null_option},
    }).init(allocator, rng.random());

    const user_val = f2.dummy(User);
    defer user_val.deinit();
    print("user_val = {}\n", user_val);
}
```

