    const v = tic.time() / 99 + @as(f32, @floatFromInt(row)) / 2;
    tic.poke(0x3ff9, @intFromFloat(2 + std.math.sin(v) * 1.2));
}

export fn TIC() void {
    tic.rect(0, 13, 92, 57, 4);
